-- T-ACC-03 (FR-ACC-004, FR-SUP-003, UC-ACC-02): record why, when and by whom an account was
-- locked, so administrators and support can see the cause. Expand-only: three nullable columns
-- and two CHECKs on a small table.

-- AlterTable (generated by prisma migrate diff from schema.prisma)
ALTER TABLE "user_account" ADD COLUMN     "lock_note" TEXT,
ADD COLUMN     "locked_at" TIMESTAMPTZ,
ADD COLUMN     "locked_by_user_id" UUID;

-- lock_reason is a code the code base switches on; a free-text reason goes in lock_note.
ALTER TABLE "user_account"
  ADD CONSTRAINT "user_account_lock_reason_check"
    CHECK (lock_reason IS NULL OR lock_reason IN ('FAILED_LOGINS', 'ADMIN_ACTION')),
  ADD CONSTRAINT "user_account_lock_note_length_check"
    CHECK (lock_note IS NULL OR char_length(lock_note) <= 500);
